package net.civeira.phylax.feature.identity.tenant.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenant.domain.Tenant;
import net.civeira.phylax.feature.identity.tenant.domain.valueobject.MarkForDeleteVO;

class MarkForDeleteValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of mark for delete of tenant")
  void test_mark_for_delete_value_holder_assign_plain_value() {
    Object holder = new Object();
    MarkForDeleteValueHolder<Object> value = new MarkForDeleteValueHolder<>(holder);
    Assertions.assertSame(holder, value.markForDelete(true), "Setters must return the holder");
    Assertions.assertTrue(value.getMarkForDeleteValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getMarkForDelete().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of mark for delete of tenant")
  void test_mark_for_delete_value_holder_assign_value_object() {
    Object holder = new Object();
    MarkForDeleteValueHolder<Object> value = new MarkForDeleteValueHolder<>(holder);
    MarkForDeleteVO vo = MarkForDeleteVO.from(true);
    Assertions.assertFalse(value.getMarkForDeleteValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.markForDelete(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getMarkForDeleteValue().orElseThrow());
    Assertions.assertSame(holder, value.markForDelete(Optional.empty()));
    Assertions.assertFalse(value.getMarkForDeleteValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.markForDelete(Optional.of(vo)));
    Assertions.assertSame(vo, value.getMarkForDeleteValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of mark for delete of tenant against the original")
  void test_mark_for_delete_value_holder_read() {
    Object holder = new Object();
    MarkForDeleteValueHolder<Object> value = new MarkForDeleteValueHolder<>(holder);
    MarkForDeleteVO vo = MarkForDeleteVO.from(true);
    MarkForDeleteVO other = MarkForDeleteVO.from(true);
    Tenant original = Mockito.mock(Tenant.class);
    Mockito.when(original.getMarkForDeleteValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readMarkForDelete(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readMarkForDelete(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.markForDelete(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readMarkForDelete(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readMarkForDelete(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of mark for delete of tenant")
  void test_mark_for_delete_value_holder_unset() {
    Object holder = new Object();
    MarkForDeleteValueHolder<Object> value = new MarkForDeleteValueHolder<>(holder);
    MarkForDeleteVO vo = MarkForDeleteVO.from(true);
    value.markForDelete(vo);
    Assertions.assertSame(holder, value.unsetMarkForDeleteIfMatches("markForDelete_other"));
    Assertions.assertTrue(value.getMarkForDeleteValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetMarkForDeleteIfMatches("markForDelete"));
    Assertions.assertFalse(value.getMarkForDeleteValue().isPresent(),
        "The field name must clear the value");
    value.markForDelete(vo);
    Assertions.assertSame(holder, value.unsetMarkForDelete());
    Assertions.assertFalse(value.getMarkForDeleteValue().isPresent(), "Unset must clear the value");
  }
}
